// DPP Atlas step 1: installable app, QR code, Updates page, Privacy page, verified rules rows.
// Run in the dpp-atlas folder:  node apply_step1.js
const fs = require("fs"), path = require("path");
const P = (...a) => path.join(...a);
const LAND = P("app", "[locale]", "page.tsx"), CHROME = P("app", "[locale]", "_ui", "chrome.tsx"), RULES = P("app", "[locale]", "rules", "page.tsx");
const LAYOUT = P("app", "layout.tsx"), SITEMAP = P("app", "sitemap.ts");
for (const f of [LAND, CHROME, RULES, LAYOUT, SITEMAP]) if (!fs.existsSync(f)) { console.log("STOP: not found: " + f + " (run inside dpp-atlas)."); process.exit(1); }
if (fs.existsSync(P("app", "[locale]", "updates", "page.tsx"))) { console.log("Already applied. Nothing to do."); process.exit(0); }
fs.mkdirSync("_backup_redesign", { recursive: true });
for (const [f, n] of [[LAND, "landing-3"], [CHROME, "chrome-3"], [RULES, "rules-3"], [LAYOUT, "layout-3"], [SITEMAP, "sitemap-3"]]) fs.copyFileSync(f, P("_backup_redesign", n + ".bak"));
let problems = 0;
function edit(file, pairs) {
  let s = fs.readFileSync(file, "utf8");
  for (const [a, b] of pairs) {
    const n = s.split(a).length - 1;
    console.log((n === 1 ? "1x " : n + "x ??") + " " + file.slice(-24) + "  " + a.slice(0, 46).replace(/\n/g, " "));
    if (n === 1) s = s.replace(a, () => b); else problems++;
  }
  fs.writeFileSync(file, s, "utf8");
}
const FILES = {"public/manifest.webmanifest": "", "public/sw.js": "", "public/icon-192.png": "", "public/icon-512.png": "", "public/icon-maskable-512.png": "", "public/apple-touch-icon.png": "", "public/qr-dpp-atlas.svg": "", "public/qr-dpp-atlas.png": "", "app/[locale]/_ui/Pwa.tsx": "", "app/[locale]/_ui/PhoneSection.tsx": "", "app/[locale]/updates/page.tsx": "", "app/[locale]/privacy/page.tsx": ""};
for (const [rel, b64] of Object.entries(FILES)) {
  fs.mkdirSync(path.dirname(rel), { recursive: true });
  fs.writeFileSync(rel, Buffer.from(b64, "base64"));
  console.log("written: " + rel);
}

// shared header and footer: Updates and Privacy links
edit(CHROME, [
  ['current: "check" | "rules" }', 'current: "check" | "rules" | "updates" | "privacy" }'],
  ['lookup: "Report lookup", login: "Log in", check: "Data Check"', 'updates: "Updates", privacy: "Privacy", lookup: "Report lookup", login: "Log in", check: "Data Check"'],
  ['lookup: "রিপোর্ট খুঁজুন", login: "লগ ইন", check: "ডেটা চেক"', 'updates: "আপডেট", privacy: "গোপনীয়তা", lookup: "রিপোর্ট খুঁজুন", login: "লগ ইন", check: "ডেটা চেক"'],
  ['{t.rules}</a>\n                        <a className="dl-lang"', '{t.rules}</a>\n            <a className="dl-hide" href={"/" + loc + "/updates"} aria-current={current === "updates" ? "page" : undefined}>{t.updates}</a>\n            <a className="dl-lang"'],
  ['<a href={"/" + loc + "/rules"}>{t.rules}</a>\n        </nav>', '<a href={"/" + loc + "/rules"}>{t.rules}</a>\n          <a href={"/" + loc + "/updates"}>{t.updates}</a>\n          <a href={"/" + loc + "/privacy"}>{t.privacy}</a>\n        </nav>'],
]);

// landing page: link, phone section, footer links
edit(LAND, [
  ['import { FIELDS } from "./check/fields";', 'import { FIELDS } from "./check/fields";\nimport PhoneSection from "./_ui/PhoneSection";'],
  ['<a className="dl-hide" href={"/" + loc + "/rules"}>{t.nav.rules}</a>\n', '<a className="dl-hide" href={"/" + loc + "/rules"}>{t.nav.rules}</a>\n            <a className="dl-hide" href={"/" + loc + "/updates"}>{isBn ? "আপডেট" : "Updates"}</a>\n'],
  ['        <section className="dl-end">', '        <PhoneSection loc={loc} />\n\n        <section className="dl-end">'],
  ['<a href={"/" + loc + "/rules"}>{t.nav.rules}</a>\n          </nav>', '<a href={"/" + loc + "/rules"}>{t.nav.rules}</a>\n            <a href={"/" + loc + "/updates"}>{isBn ? "আপডেট" : "Updates"}</a>\n            <a href={"/" + loc + "/privacy"}>{isBn ? "গোপনীয়তা" : "Privacy"}</a>\n          </nav>'],
]);

// root layout: manifest, icons, theme colour, register the service worker
edit(LAYOUT, [
  ['import "./globals.css";', 'import "./globals.css";\nimport { PwaRegister } from "./[locale]/_ui/Pwa";'],
  ['export const metadata: Metadata = {', 'export const viewport = { themeColor: "#0f766e" };\n\nexport const metadata: Metadata = {\n  manifest: "/manifest.webmanifest",\n  icons: { icon: "/icon-192.png", apple: "/apple-touch-icon.png" },'],
  ['<body style={{margin:0, padding:0}}>{children}</body>', '<body style={{margin:0, padding:0}}>{children}<PwaRegister /></body>'],
]);

// sitemap
edit(SITEMAP, [['    { url: base + "/bn/rules", lastModified: now, changeFrequency: "monthly", priority: 0.7 },', '    { url: base + "/bn/rules", lastModified: now, changeFrequency: "monthly", priority: 0.7 },\n    { url: base + "/en/updates", lastModified: now, changeFrequency: "weekly", priority: 0.6 },\n    { url: base + "/bn/updates", lastModified: now, changeFrequency: "weekly", priority: 0.6 },\n    { url: base + "/en/privacy", lastModified: now, changeFrequency: "yearly", priority: 0.3 },\n    { url: base + "/bn/privacy", lastModified: now, changeFrequency: "yearly", priority: 0.3 },']]);

// rules page: verified destruction-ban row, new Decision 2026/1736 row
let r = fs.readFileSync(RULES, "utf8");
const ban = r.match(/^ *\{ name: "EU ban on destroying unsold apparel and footwear \(ESPR\)"[^\n]*\n/m);
if (ban) {
  const NEW_BAN = '  { name: "EU ban on destroying unsold clothes, clothing accessories and footwear (ESPR)", type: "EU law", typeBn: "ইইউ আইন", what: "Applies to large companies from 19 July 2026; medium-sized companies follow from 2030. Destruction is allowed only in limited cases such as unsafe, damaged or counterfeit items. Companies relying on an exemption must keep proof, publish annual reports and keep records for five years. Mainly a brand and retailer duty. The page read does not give the article number.", source: "European Commission, environment news, 17 July 2026", whatBn: "বড় কোম্পানির জন্য ১৯ জুলাই ২০২৬ থেকে কার্যকর; মাঝারি কোম্পানির জন্য ২০৩০ থেকে। ধ্বংস শুধু সীমিত ক্ষেত্রে অনুমোদিত, যেমন অনিরাপদ, ক্ষতিগ্রস্ত বা জাল পণ্য। ছাড়ের ওপর নির্ভর করলে প্রমাণ রাখতে হবে, বার্ষিক রিপোর্ট প্রকাশ করতে হবে এবং পাঁচ বছর নথি রাখতে হবে। মূলত ব্র্যান্ড ও খুচরা বিক্রেতার দায়িত্ব। পড়া পাতায় ধারার নম্বর দেওয়া নেই।", sourceBn: "ইউরোপীয় কমিশন, পরিবেশ সংবাদ, ১৭ জুলাই ২০২৬", status: "checked" },\n';
  r = r.replace(ban[0], () => NEW_BAN); console.log("1x rules: destruction-ban row replaced");
} else { console.log("0x ?? rules: destruction-ban row not found"); problems++; }
const reg = r.match(/^ *\{ name: "ESPR Article 13 central DPP registry[^\n]*\n/m);
if (reg) {
  const NEW_DEC = '  { name: "Commission Implementing Decision (EU) 2026/1736: harmonised standards for digital product passports", type: "EU implementing decision", typeBn: "ইইউ বাস্তবায়ন সিদ্ধান্ত", what: "Dated 14 July 2026 and in force from 15 July 2026. The list of standards and their legal effect were not reviewed here.", source: "EUR-Lex (excerpt page)", whatBn: "তারিখ ১৪ জুলাই ২০২৬, কার্যকর ১৫ জুলাই ২০২৬ থেকে। স্ট্যান্ডার্ডের তালিকা ও আইনগত প্রভাব এখানে পর্যালোচনা করা হয়নি।", sourceBn: "EUR-Lex (সারাংশ পাতা)", status: "limited" },\n';
  r = r.replace(reg[0], () => reg[0] + NEW_DEC); console.log("1x rules: Decision 2026/1736 row added");
} else { console.log("0x ?? rules: registry row not found"); problems++; }
fs.writeFileSync(RULES, r, "utf8");

if (problems) console.log("\n" + problems + " item(s) did not match. Do NOT push. Send me this output.");
else console.log("\nDone. Next: npm run build, then git add . / git commit -m \"Add installable app, QR, updates, privacy\" / git push (one at a time).");
